-- public.shore_near(p_world uuid, p_x double precision, p_y double precision, p_range integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.shore_near(p_world uuid, p_x double precision, p_y double precision, p_range integer DEFAULT 2)
 RETURNS TABLE(x integer, y integer)
 LANGUAGE sql
 STABLE
AS $function$
  select t.x, t.y from
    (select floor(p_x)::int + dx as x, floor(p_y)::int + dy as y,
            sqrt(dx ^ 2 + dy ^ 2) as d
     from generate_series(-p_range, p_range) dx, generate_series(-p_range, p_range) dy) t
  where in_bounds(p_world, t.x, t.y) and passable(p_world, t.x, t.y)
    and not has_water(p_world, t.x, t.y)
  order by t.d
  limit 1
$function$
